import json, math

def verify(answer):
    # Mechanical GRPO verifier for batch-006 scenario 1 (The Saturated Confidence).
    # Recomputes sigmoid activation/derivative, quadratic vs cross-entropy gradient
    # factors and ratio, the smooth-objective veto, and both initializer z std devs.
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "sigmoid_a", "sigmoid_prime", "quadratic_gradient_factor",
        "crossentropy_gradient_factor", "ce_over_quadratic_ratio",
        "quadratic_learns_fast_when_wrong", "crossentropy_learns_fast_when_wrong",
        "win_count_is_smooth", "z_std_unscaled_init", "z_std_scaled_init",
        "scaled_init_avoids_saturation", "decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    def close(key, val, rel=1e-6, abs_=1e-9):
        x = answer.get(key)
        return num(x) and math.isclose(x, val, rel_tol=rel, abs_tol=abs_)
    z, y, n_in = 7.0, 0.0, 1000
    a = 1.0 / (1.0 + math.exp(-z))
    sp = a * (1.0 - a)
    quad = (a - y) * sp
    ce = (a - y)
    if not close("sigmoid_a", a):
        return False
    if not close("sigmoid_prime", sp):
        return False
    if not close("quadratic_gradient_factor", quad):
        return False
    if not close("crossentropy_gradient_factor", ce):
        return False
    if not close("ce_over_quadratic_ratio", ce / quad):
        return False
    if answer.get("quadratic_learns_fast_when_wrong") is not False:
        return False
    if answer.get("crossentropy_learns_fast_when_wrong") is not True:
        return False
    if answer.get("win_count_is_smooth") is not False:
        return False
    if not close("z_std_unscaled_init", math.sqrt(n_in / 2.0 + 1.0)):
        return False
    if not close("z_std_scaled_init", math.sqrt(0.5 + 1.0 / n_in)):
        return False
    if answer.get("scaled_init_avoids_saturation") is not True:
        return False
    if answer.get("decision") != "veto_and_recompute":
        return False
    return True

import json, math

def verify(answer):
    # Mechanical GRPO verifier for batch-006 scenario 2 (The Overfit Elephant).
    # Recomputes overfit gaps, held-out test comparison, the tuning-split veto,
    # and the parameter-count veto.
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "model_A_overfit_gap", "model_B_overfit_gap",
        "model_A_test_accuracy", "model_B_test_accuracy",
        "select_by_train_accuracy_admissible", "better_model_by_heldout",
        "tuned_on_test_data_valid", "correct_tuning_split",
        "more_params_guarantees_better", "decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    def close(key, val, rel=1e-6, abs_=1e-9):
        x = answer.get(key)
        return num(x) and math.isclose(x, val, rel_tol=rel, abs_tol=abs_)
    a_train, a_test = 0.99, 0.82
    b_train, b_test = 0.90, 0.88
    if not close("model_A_overfit_gap", a_train - a_test):
        return False
    if not close("model_B_overfit_gap", b_train - b_test):
        return False
    if not close("model_A_test_accuracy", a_test):
        return False
    if not close("model_B_test_accuracy", b_test):
        return False
    if answer.get("select_by_train_accuracy_admissible") is not False:
        return False
    better = "A" if a_test > b_test else "B"
    if answer.get("better_model_by_heldout") != better:
        return False
    if answer.get("tuned_on_test_data_valid") is not False:
        return False
    if answer.get("correct_tuning_split") != "validation":
        return False
    if answer.get("more_params_guarantees_better") is not False:
        return False
    if answer.get("decision") != "veto_and_recompute":
        return False
    return True

